-- ====== i18n Refund Regulations ======
IF NOT EXISTS (SELECT 1 FROM SystemSettings WHERE SettingKey = 'RefundRegulations') INSERT INTO SystemSettings (SettingKey, SettingValue, Description, UpdatedAt) VALUES ('RefundRegulations', N'<p class="font-semibold text-slate-800">Chính sách hoàn tiền theo ngày khởi hành:</p><ul class="list-disc pl-5 space-y-2"><li>Hủy trên 7 ngày trước khi khởi hành: Hoàn tiền 100% (Không tính phí).</li><li>Hủy từ 3 đến 7 ngày trước khi khởi hành: Hoàn tiền 50% (Phí hủy 50%).</li><li>Hủy dưới 3 ngày trước khi khởi hành: Hoàn tiền 0% (Phí hủy 100%).</li></ul><div class="rounded-xl border border-amber-200 bg-amber-50/50 p-3.5 text-xs text-amber-800 mt-4"><p class="mb-1 font-bold">Lưu ý về voucher:</p><ul class="list-disc pl-4 space-y-1"><li>Voucher không được hoàn lại trong mọi trường hợp hủy tour.</li><li>Tổng tiền hoàn lại sẽ tính trên giá trị thanh toán thực tế (sau khi đã trừ voucher).</li></ul></div>', 'RefundRegulations', GETDATE()); ELSE UPDATE SystemSettings SET SettingValue = N'<p class="font-semibold text-slate-800">Chính sách hoàn tiền theo ngày khởi hành:</p><ul class="list-disc pl-5 space-y-2"><li>Hủy trên 7 ngày trước khi khởi hành: Hoàn tiền 100% (Không tính phí).</li><li>Hủy từ 3 đến 7 ngày trước khi khởi hành: Hoàn tiền 50% (Phí hủy 50%).</li><li>Hủy dưới 3 ngày trước khi khởi hành: Hoàn tiền 0% (Phí hủy 100%).</li></ul><div class="rounded-xl border border-amber-200 bg-amber-50/50 p-3.5 text-xs text-amber-800 mt-4"><p class="mb-1 font-bold">Lưu ý về voucher:</p><ul class="list-disc pl-4 space-y-1"><li>Voucher không được hoàn lại trong mọi trường hợp hủy tour.</li><li>Tổng tiền hoàn lại sẽ tính trên giá trị thanh toán thực tế (sau khi đã trừ voucher).</li></ul></div>' WHERE SettingKey = 'RefundRegulations';

IF NOT EXISTS (SELECT 1 FROM SystemSettings WHERE SettingKey = 'RefundRegulations_en') INSERT INTO SystemSettings (SettingKey, SettingValue, Description, UpdatedAt) VALUES ('RefundRegulations_en', N'<p class="font-semibold text-slate-800">Refund policy by departure date:</p><ul class="list-disc pl-5 space-y-2"><li>Cancellation more than 7 days before departure: 100% refund (No fee).</li><li>Cancellation 3 to 7 days before departure: 50% refund (50% fee).</li><li>Cancellation less than 3 days before departure: 0% refund (100% fee).</li></ul><div class="rounded-xl border border-amber-200 bg-amber-50/50 p-3.5 text-xs text-amber-800 mt-4"><p class="mb-1 font-bold">Note on vouchers:</p><ul class="list-disc pl-4 space-y-1"><li>Vouchers are non-refundable in all cases of tour cancellation.</li><li>Total refund amount will be calculated based on the actual payment value (after deducting voucher).</li></ul></div>', 'RefundRegulations_en', GETDATE()); ELSE UPDATE SystemSettings SET SettingValue = N'<p class="font-semibold text-slate-800">Refund policy by departure date:</p><ul class="list-disc pl-5 space-y-2"><li>Cancellation more than 7 days before departure: 100% refund (No fee).</li><li>Cancellation 3 to 7 days before departure: 50% refund (50% fee).</li><li>Cancellation less than 3 days before departure: 0% refund (100% fee).</li></ul><div class="rounded-xl border border-amber-200 bg-amber-50/50 p-3.5 text-xs text-amber-800 mt-4"><p class="mb-1 font-bold">Note on vouchers:</p><ul class="list-disc pl-4 space-y-1"><li>Vouchers are non-refundable in all cases of tour cancellation.</li><li>Total refund amount will be calculated based on the actual payment value (after deducting voucher).</li></ul></div>' WHERE SettingKey = 'RefundRegulations_en';

-- ====== i18n About Us ======
IF NOT EXISTS (SELECT 1 FROM SystemSettings WHERE SettingKey = 'AboutUs') INSERT INTO SystemSettings (SettingKey, SettingValue, Description, UpdatedAt) VALUES ('AboutUs', N'Hoạt động như một "Hệ thống Quản lý Tour Thông minh", StayHub được thiết kế để các công ty du lịch quản lý hiệu quả tour, lịch trình, đặt chỗ, tương tác khách hàng và nội dung du lịch trong một hệ sinh thái thống nhất. Hệ thống tích hợp tính năng đề xuất tour bằng AI, quản lý lịch trình thông minh, mạng xã hội và vận hành đa vai trò nhằm tạo ra một trải nghiệm du lịch toàn diện và liền mạch. StayHub cũng cho phép các doanh nghiệp quản lý thông tin điểm đến như di sản văn hóa, đặc sản địa phương, ẩm thực truyền thống và các điểm du lịch để cung cấp nội dung phong phú và đáng tin cậy hơn cho khách hàng.', 'AboutUs', GETDATE()); ELSE UPDATE SystemSettings SET SettingValue = N'Hoạt động như một "Hệ thống Quản lý Tour Thông minh", StayHub được thiết kế để các công ty du lịch quản lý hiệu quả tour, lịch trình, đặt chỗ, tương tác khách hàng và nội dung du lịch trong một hệ sinh thái thống nhất. Hệ thống tích hợp tính năng đề xuất tour bằng AI, quản lý lịch trình thông minh, mạng xã hội và vận hành đa vai trò nhằm tạo ra một trải nghiệm du lịch toàn diện và liền mạch. StayHub cũng cho phép các doanh nghiệp quản lý thông tin điểm đến như di sản văn hóa, đặc sản địa phương, ẩm thực truyền thống và các điểm du lịch để cung cấp nội dung phong phú và đáng tin cậy hơn cho khách hàng.' WHERE SettingKey = 'AboutUs';

IF NOT EXISTS (SELECT 1 FROM SystemSettings WHERE SettingKey = 'AboutUs_en') INSERT INTO SystemSettings (SettingKey, SettingValue, Description, UpdatedAt) VALUES ('AboutUs_en', N'Operating as an "Intelligent Tour Management System", StayHub is designed for travel companies to efficiently manage tours, schedules, bookings, customer interactions, and tourism-related content within a unified ecosystem. The system integrates AI-powered tour recommendations, smart itinerary management, social interaction features, and multi-role operations to create a comprehensive and seamless travel experience. StayHub also enables businesses to manage destination information such as cultural heritage sites, local specialties, traditional foods, and tourist attractions to provide richer and more reliable travel content for customers.', 'AboutUs_en', GETDATE()); ELSE UPDATE SystemSettings SET SettingValue = N'Operating as an "Intelligent Tour Management System", StayHub is designed for travel companies to efficiently manage tours, schedules, bookings, customer interactions, and tourism-related content within a unified ecosystem. The system integrates AI-powered tour recommendations, smart itinerary management, social interaction features, and multi-role operations to create a comprehensive and seamless travel experience. StayHub also enables businesses to manage destination information such as cultural heritage sites, local specialties, traditional foods, and tourist attractions to provide richer and more reliable travel content for customers.' WHERE SettingKey = 'AboutUs_en';
